stages.helpers:
float sdSphere(vec3 p, float r) {
  return length(p) - r;
}

float sdBox(vec3 p, vec3 b) {
  vec3 q = abs(p) - b;
  return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

float map(vec3 p) {
  float ball = sdSphere(p - vec3(0.0, 0.0, 3.0), 1.0);
  float ground = sdBox(p - vec3(0.0, -2.0, 4.0), vec3(20.0, 1.0, 4.0));
  return min(ball, ground);
}

float march(vec3 ro, vec3 rd) {
  float t = 0.0;
  for (int i = 0; i < 64; i++) {
    vec3 p = ro + rd * t;
    float d = map(p);
